import{_ as i,h as t,i as e,c as r,v as l,p,x as o,m as s,e as d,S as h}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"Analogical prompting","description":"","frontmatter":{"title":"Analogical prompting","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/analogical-prompting.md","filePath":"llm/analogical-prompting.md","lastUpdated":1788454257000}'),c={name:"llm/analogical-prompting.md"};function m(g,a,u,E,A,_){const n=t("Mermaid");return e(),r("div",null,[a[1]||(a[1]=l('<h1 id="analogical-prompting" tabindex="-1">Analogical prompting <a class="header-anchor" href="#analogical-prompting" aria-label="Permalink to &quot;Analogical prompting&quot;">​</a></h1><div class="epigraph"><p>先回忆与当前问题相关的例题或知识，再动手解题；示范不必由人写进提示，模型自己生成的类比往往更贴这道题。</p><footer>—— Yasunaga et al., Large Language Models as Analogical Reasoners, ICLR 2024</footer></div><p>少样本思维链的质量绑在示范上：例题要相关、步骤要对、分布要对齐测试集。Yasunaga、Chen、Bosselut、Liang 与 Manning 把认知科学里的类比推理收成一条提示：解题之前，先让模型<strong>自生成</strong>若干相关问题及其解法（或一段相关知识），再条件化到原题上。这就是 analogical prompting。它仍是一次或少数几次解码，不检索外部题库，也不微调。相对人工少样本，省掉了例题工程；相对纯零样本 CoT，多了一段「临时题库」当脚手架。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>少样本 CoT 假定提示里的例题与测试题同构。竞赛数学、编程竞赛、新任务上，同构例题很难事先备齐：要么太泛，变成格式说明书；要么太窄，把解法锁进示范里出现过的数字模式。人工选题还有污染与过拟合提示的风险。零样本 CoT 没有例题，又回到粒度失控、缺步、不会调用相关定理的老问题。</p><p>类比提示要回答的是：模型参数里已经存了大量题解，能否在测试时先把「相似题」从权重里采样出来，当作这次任务的专用少样本，而不经过外部分析器。若生成的例题真相关，后续解题等于在一次前向里做了「检索参数 + 推理」；若例题只是表面相似或解法错误，脚手架会把原题带歪。</p><h3 id="少样本示范的错配" tabindex="-1">少样本示范的错配 <a class="header-anchor" href="#少样本示范的错配" aria-label="Permalink to &quot;少样本示范的错配&quot;">​</a></h3><p>固定例题对所有测试题共用同一组条件前缀。对简单题，示范过长是浪费；对偏题，示范从未覆盖所需引理。提示工程于是变成维护题库。类比提示把题库生成推迟到看见测试题之后，相关性由模型自己估计。这不是证明模型会检索到最优邻域，只是把「选题」从人挪到同一套 \\(\\pi\\) 上。</p><p><span class="marginnote">自生成例题会泄漏测试题的数字或变量名，变成变相抄题而不是类比。指令里应明确要求「相关但不同的问题」，并在分析时检查例题与原题的表面重叠。重叠极高时，增益可能来自复述而不是类比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准模板分三块。第一块点明目标：为当前问题召回相关问题。第二块让模型写出 \\(K\\) 道相关题，每题带简要解法（论文常用 \\(K=3\\) 到 \\(5\\)）。第三块给出原题，要求参照刚写出的例题作答。知识型变体把「相关问题」换成「相关概念、定理或算法要点」，适合需要陈述性知识、例题不好编的任务。两条变体都是零样本：不提供任何人工题解。</p><p>解码可以一次完成（例题与解答连在同一条补全里），也可以先停在例题末尾再续写解答，便于单独检查例题质量。Yasunaga 等人在 GSM8K、MATH、Codeforces 风格编程、以及 BIG-Bench 的若干推理任务上评估，对照零样本 CoT、少样本 CoT 和检索真实相似题。主结论是：自生成例题在多个设置上匹配或超过固定少样本，且不需要标签。</p>',12)),(e(),p(h,null,{default:o(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%BD%93%E5%89%8D%E9%97%AE%E9%A2%98%20x%22%5D%20--%3E%20R%5B%22%E7%94%9F%E6%88%90%E7%9B%B8%E5%85%B3%E4%BE%8B%E9%A2%98%E6%88%96%E7%9F%A5%E8%AF%86%22%5D%0A%20%20R%20--%3E%20Y%5B%22%E6%9D%A1%E4%BB%B6%E5%8C%96%E5%88%B0%20x%20%E4%B8%8A%E6%B1%82%E8%A7%A3%22%5D%0A%20%20F%5B%22%E4%BA%BA%E5%B7%A5%E5%B0%91%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20Y2%5B%22%E7%9B%B4%E6%8E%A5%20CoT%22%5D%0A%20%20X%20--%3E%20Y2%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="先回忆再解题" tabindex="-1">先回忆再解题 <a class="header-anchor" href="#先回忆再解题" aria-label="Permalink to &quot;先回忆再解题&quot;">​</a></h3><p>「回忆」在这里是生成，不是查库。模型被要求输出完整的迷你题解，而不是关键词列表。题解需要足够具体，后续才能当示范：只有「这是一道方程题」没有步骤，类比段等于零样本。温度可略高于最终作答，以鼓励例题多样性；最终作答应更保守，以免在错误类比上发散。\\(K\\) 增大则上下文变长、延迟变长，例题之间还可能互相矛盾，需要在验证集上扫，而不是默认越大越好。</p><h3 id="自生成例题如何当条件" tabindex="-1">自生成例题如何当条件 <a class="header-anchor" href="#自生成例题如何当条件" aria-label="Permalink to &quot;自生成例题如何当条件&quot;">​</a></h3><p>机制上，相关题解进入上下文后，原题的逐步推导会模仿刚写出的格式与引理。这和少样本 CoT 相同，只是例题分布依赖于 \\(x\\)。依赖 \\(x\\) 是优点也是风险：优点是相关；风险是例题生成器用的是同一套会在原题上犯错的知识。若模型系统性不会某类积分，它生成的「相关积分题」也会错，原题跟着错。类比不能创造参数里没有的算法，只能重新组织已有的解题程序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>认知科学里的类比是「源问题的关系结构映射到目标问题」。提示并不能保证模型做结构映射：它可能只是抄格式、抄语气。有效时，源问题提供的是中间引理和步骤模板；无效时，源问题提供的是错误的表面特征（都出现「火车」，于是用了行程公式，其实是组合计数）。因此类比提示的增益应在「需要相关引理」的任务上更大，在纯格式任务上接近普通 CoT。</p><p>与检索增强的差别是记忆位置。RAG 读文档；类比提示读权重。没有引用、没有更新、也没有权限边界。事实类任务上，自生成「相关知识」可以是一本过期的内部百科，听起来很像对。应用时应限制在数学、代码、谜题等可验证域，或把生成的知识当假设再检索核对。</p><p><span class="marginnote">把类比段交给较小的模型、把解题交给较大的模型，看起来像分层，其实例题质量会先塌。论文的设定是同一模型既出例题又解题。若要分层，必须单独测「小模型例题 + 大模型解题」是否仍优于大模型零样本。</span></p><h3 id="类比失败时会发生什么" tabindex="-1">类比失败时会发生什么 <a class="header-anchor" href="#类比失败时会发生什么" aria-label="Permalink to &quot;类比失败时会发生什么&quot;">​</a></h3><p>三种典型失败。例题不相关：后续相当于噪声少样本，通常略差于干净零样本。例题相关但解错：错误解法被当成权威示范，危害大于没有例题。例题太像原题：模型把原题数字填进例题答案，造成虚假高相关。缓解包括：要求例题使用不同数值、限制例题长度、对可编程任务先跑例题中的代码（若有）再继续。没有检查器时，宁可 \\(K=1\\) 条短而对的提纲，不要五条华丽的错解。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>延迟和费用按「例题 token + 解答 token」增长，相对零样本 CoT 往往贵一倍以上。产品上应只对高难度、可验证的请求开启，并设最大例题长度。竞赛数学与编程是原文主场；开放聊天、安全敏感咨询不适合让模型先编三道「相关案例」。与 <a href="/llm/plan-and-solve">Plan-and-Solve</a> 可以叠：先类比再计划再求解，但叠加后错误归因极难，应先单独开一类比。</p><p>它不能替代少样本里那些<strong>任务格式</strong>示范（输出 JSON 的字段顺序、单位、评分协议）。格式仍应写死在系统提示里；类比只负责内容侧的题解。也不要和「从题库检索真题」混名：后者有版权与污染问题，前者有幻觉问题，治理手段不同。</p><p><span class="marginnote">评测必须用原题答案的硬指标，不要用「例题看起来相关」的人工印象当成功。相关而错的例题会同时提高相关性和降低准确率，只看前者会得出相反的产品结论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Analogical prompting 让模型先自生成相关例题或知识，再解当前题，把选题从人工少样本挪到测试时生成。</li><li>相关例题是同一 \\(\\pi\\) 从权重里采样的脚手架，不能引入参数中不存在的算法。</li><li>知识型变体适合陈述性要点；题解型变体适合数学与代码。</li><li>失败模式是不相关、相关但解错、以及几乎复制原题；后两种比没有例题更糟。</li><li>费用随例题长度增长；应限制在可验证域，并与格式示范分开写。</li><li>与检索真题、与智能体规划都不是同一件事。</li><li>出处：Yasunaga et al., <em>Large Language Models as Analogical Reasoners</em>, ICLR 2024。</li></ul>',16))])}const T=i(c,[["render",m]]);export{f as __pageData,T as default};
